interface Notifier { void send(String message); }
class Registration {
    // 구체적인 전송 방법 대신 역할에 의존해요.
    private final Notifier notifier;
    Registration(Notifier notifier) { this.notifier = notifier; }
    void welcome(String name) {
        // 전송은 주입받은 객체에 맡겨요.
        notifier.send("환영해요, " + name);
    }
}

